let config={}; const $=id=>({value:({dose:config.dose,milk:config.milk,grind:"medium-fine",froth:"wand"})[id]});
const defs=`<defs><filter id="handdrawn" x="-8%" y="-8%" width="116%" height="116%"><feTurbulence type="fractalNoise" baseFrequency=".025" numOctaves="2" seed="8" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale="1.25" xChannelSelector="R" yChannelSelector="G"/></filter><linearGradient id="metal"><stop stop-color="#f7f4eb"/><stop offset="1" stop-color="#f7f4eb"/></linearGradient><linearGradient id="sage"><stop stop-color="#e6e7d7"/><stop offset="1" stop-color="#e6e7d7"/></linearGradient><linearGradient id="milkPaint"><stop stop-color="#f5e5c9"/><stop offset="1" stop-color="#f5e5c9"/></linearGradient></defs>`;
const shadow=(x=300,y=292,rx=125)=>`<path d="M${x-rx} ${y} Q${x} ${y+4} ${x+rx} ${y-1}" fill="none" stroke="#c7c8b8" stroke-width="1.2"/>`;
const label=(x,y,t)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="10" fill="#7c806f" stroke="none">${t}</text>`;
function base(x=0,y=0){return `<g transform="translate(${x} ${y})" stroke="#5c6053" stroke-width="2.2"><path d="M249 175 L337 174 354 257 335 275 249 273 232 257Z" fill="#f7f4eb"/><path d="M264 181 L268 269 M320 181 L318 270 M249 175 L249 258 267 273 M337 175 L338 258 335 275" fill="none" stroke-width="1.5"/><ellipse cx="293" cy="175" rx="44" ry="11" fill="#e3e2d3"/><ellipse cx="293" cy="174" rx="36" ry="7" fill="#f7f4eb" stroke-width="1.3"/><circle cx="337" cy="206" r="5" fill="#bc6150" stroke-width="1.2"/></g>`}
function top(x=0,y=0){return `<g transform="translate(${x} ${y})" stroke="#5c6053" stroke-width="2.2"><path d="M340 99 Q390 79 389 124 L385 159 Q378 172 356 162 L355 147 Q372 151 374 139 L376 115 Q375 107 347 116Z" fill="#394c3d"/><path d="M248 95 L337 94 353 168 336 183 249 183 234 169 226 126 212 110 242 113Z" fill="#f7f4eb"/><path d="M264 100 L268 176 M318 99 L317 177 M248 96 L251 168 268 182 M337 95 L337 167 336 183 M234 168 L251 168 268 177 317 177 337 167 353 168" fill="none" stroke-width="1.5"/><path d="M248 94 L291 77 338 93 317 103 268 103Z" fill="#efeee3"/><path d="M284 79 Q280 65 292 65 Q303 64 301 78" fill="#b94c3e" stroke="#b94c3e"/><path d="M251 184 Q293 188 337 183" fill="none"/></g>`}
function basket(x=0,y=0,fill=1){return `<g transform="translate(${x} ${y})" stroke="#606456" stroke-width="2"><path d="M242 146 L251 190 281 205 281 245 299 246 300 205 331 191 342 146Z" fill="#efeee4"/><ellipse cx="292" cy="146" rx="50" ry="14" fill="#f7f4eb"/><ellipse cx="292" cy="146" rx="44" ry="10" fill="${fill?'#674635':'#e2e2d5'}" stroke-width="1"/>${fill?Array.from({length:30},(_,i)=>`<path d="M${255+(i*17)%73} ${140+(i*7)%12} l2 1" stroke="#aa8061" stroke-width="1"/>`).join(''):''}</g>`}
function mug(x=0,y=0,fill=0,foam=false){return `<g transform="translate(${x} ${y})" stroke="#364b39" stroke-width="2.5"><ellipse cx="300" cy="268" rx="100" ry="27" fill="#d69aaf" stroke="#c787a2"/><ellipse cx="300" cy="268" rx="80" ry="19" fill="none" stroke="#ebc3cf" stroke-width="1.3"/><path d="M353 162 C412 134 413 224 354 222 L354 207 C388 216 390 165 358 180Z" fill="#354c38"/><path d="M239 157 L247 233 Q254 259 301 259 Q344 259 353 231 L362 157Z" fill="#354c38"/><path d="M244 187 Q299 208 358 187" fill="none" stroke="#eeede0" stroke-width="1.2"/><ellipse cx="300" cy="157" rx="62" ry="20" fill="#f7f4eb"/><ellipse cx="300" cy="158" rx="53" ry="13" fill="${fill?foam?'#d7b896':'#704a37':'#f7f4eb'}" stroke="${fill?'#78523e':'#e0ded0'}" stroke-width="1.5"/>${foam?`<path d="M279 157 C268 142 282 145 300 150 C324 139 334 153 300 165Z" fill="#f7efdd" stroke="none"/>`:''}</g>`}
function pitcher(x=0,y=0,rot=0){return `<g transform="translate(${x} ${y}) rotate(${rot} 292 170)" stroke="#626456" stroke-width="2.2"><path d="M338 149 Q370 143 368 181 Q368 205 338 201 L340 189 Q356 192 356 171 Q356 160 340 161Z" fill="#f7f4eb"/><path d="M243 138 L257 243 Q293 258 337 243 L344 142 357 126 322 137Z" fill="#efeee5"/><path d="M260 157 L270 234" fill="none" stroke="#bbbdae" stroke-width="1.3"/><ellipse cx="293" cy="138" rx="49" ry="13" fill="#f7f4eb"/><ellipse cx="293" cy="139" rx="41" ry="9" fill="#f6e5c8" stroke-width="1.1"/></g>`}
function steam(x,y,t){return [0,1,2].map(i=>`<path d="M${x+i*15} ${y} q -10 -13 0 -25 t 0 -25" stroke="#9b9e89" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="${.25+.25*Math.sin(t*6+i)}" transform="translate(0 ${-t*8})"/>`).join('')}
const steps=[
{short:'磨咖啡豆',title:'从新鲜研磨开始。',desc:()=>`将称好的 ${$('dose').value || '适量'} g 咖啡豆磨成${$('grind').value==='medium'?'中等':'中细'}粗细，像细砂而非浓缩粉末。最终标准是你自己的粉篮松散装满并刮平。`,safe:'粉重用于记录你自己粉篮的容量，不是通用配方。',scene:t=>{let r=t*900;return shadow()+`<g><rect x="254" y="105" width="80" height="144" rx="16" fill="url(#sage)"/><ellipse cx="294" cy="107" rx="40" ry="11" fill="#e5eadb"/><ellipse cx="294" cy="110" rx="25" ry="6" fill="#77543c"/><path d="M254 205 H334 V251 Q296 268 254 251Z" fill="url(#metal)"/><ellipse cx="294" cy="205" rx="39" ry="8" fill="#7f8d75"/><rect x="290" y="76" width="8" height="28" rx="4" fill="#9aa48f"/><g transform="rotate(${Math.sin(r/70)*25} 294 77)"><path d="M294 78 H355" stroke="#839176" stroke-width="7" stroke-linecap="round"/><rect x="345" y="61" width="28" height="21" rx="9" fill="#4f5c43"/></g></g>`+label(294,298,'摩卡壶研磨 · 不要细成粉末') }},
{short:'加水',title:'给安全阀留出空间。',desc:()=>`壶体冷却时，将常温清水加入下壶，停在安全阀下方。以实际安全阀的位置为准，不要照搬固定毫升数。`,safe:'不要淹没安全阀。下壶只加水，绝不加奶。',scene:t=>{let f=Math.min(t*1.7,1),y=259-f*43;return shadow()+base()+`<path d="M249 180 L338 180 348 257 334 267 251 267 240 257Z" fill="#f4f7ef" opacity=".6"/><path d="M${245+f*3} ${y} H${344-f*4} L348 257 334 267 251 267 240 257Z" fill="#a0c8d0" opacity=".9"/><ellipse cx="293" cy="${y}" rx="${48-f*3}" ry="8" fill="#c3e0e1"/><circle cx="337" cy="206" r="5" fill="#b38a4d"/><path d="M345 206 H402" stroke="#a28761" stroke-dasharray="3 4"/>`+label(432,210,'安全阀')+(t<.65?`<g transform="rotate(20 236 95)"><path d="M165 56 H223 L240 122 H173Z" fill="url(#metal)"/><path d="M223 72 L257 85 234 107Z" fill="#b7c2ac"/></g><path d="M255 98 Q280 130 280 ${y}" stroke="#b2d5dd" stroke-width="7" fill="none"/>`:'')+label(293,302,'剖面示意 · 水位停在安全阀下方') }},
{short:'装咖啡粉',title:'装满、刮平，不压粉。',desc:()=>`将${$('grind').value==='medium'?'中等':'中细'}研磨的咖啡粉松散装满粉篮，轻轻刮平。想下次复现，可以称量这一篮，在配方中记下粉重。`,safe:'不要压粉、堆高，也不要故意只装半篮。',scene:t=>{let f=t>.45;return shadow()+basket(0,0,f)+`<g transform="translate(${t<.5?-30+t*80:40} ${t<.5?-50:-75}) rotate(${t<.5?20:0} 290 130)"><ellipse cx="290" cy="123" rx="29" ry="10" fill="#bac5ae"/><path d="M313 123 H389" stroke="#a6b39a" stroke-width="7" stroke-linecap="round"/>${!f?'<ellipse cx="290" cy="120" rx="23" ry="8" fill="#765239"/>':''}</g>`+(t>.15&&t<.5?Array.from({length:22},(_,i)=>`<circle cx="${270+i%7*6}" cy="${80+(i*13+t*180)%55}" r="1.5" fill="#78543b"/>`).join(''):'')+label(292,296,'与粉篮边缘齐平 · 不压粉') }},
{short:'拧合摩卡壶',title:'把它们轻轻组合起来。',desc:()=>`装好粉篮，清理壶口残留的咖啡粉，再将上下壶拧紧。握住壶身，不用手柄发力。确认密封圈和滤网干净、安装到位。`,safe:'本演示使用常温水。若厂家要求使用热水，务必保护双手避免烫伤。热壶或带压时绝不能打开。',scene:t=>{let dy=-75*(1-Math.min(t*1.5,1));return shadow()+base()+top(Math.sin(t*15)*(1-t)*3,dy)+label(293,304,t<.65?'对齐螺纹，稳稳拧合':'握住壶身拧紧，不要用手柄发力') }},
{short:'小火冲煮',title:'让咖啡慢慢流出来。',desc:()=>`在兼容的炉具上使用小到中火。燃气火焰不要超过壶底。留意出液，咖啡收集完成、出液结束时及时离火。`,safe:'不要离开看管，也不要让咖啡沸腾。若异常不出液或安全阀排气，关火并完全冷却后再检查。动画不是冲煮计时器。',scene:t=>{let x=t>.72?(t-.72)*160:0;return shadow()+`<ellipse cx="293" cy="278" rx="82" ry="18" fill="#d7dbcf"/><ellipse cx="293" cy="273" rx="60" ry="12" fill="#53604a"/><ellipse cx="293" cy="270" rx="44" ry="7" fill="none" stroke="${t>.72?'#8a967d':'#dd9674'}" stroke-width="5"/>`+`<g transform="translate(${x} ${t>.72?-10:0})">${base(0,-4)}${top(0,-4)}${t>.3?steam(279,64,t):''}</g>`+label(293,320,t>.72?'及时离火 · 等壶冷却':'小到中火 · 火焰不要超过壶底') }},
{short:'温奶与打泡',title:'打出一点柔软的奶泡。',desc:()=>{let m=$('froth').value;return m==='electric'?`加入 ${$('milk').value} ml 牛奶，但必须处于奶泡机允许的奶量 / 奶泡刻度内。按设备说明运行温热奶泡程序。`:`将 ${$('milk').value} ml 奶单独温热，不要煮沸。容器留出足够空间。${m==='wand'?'先把打奶头浸入奶中，再开机轻轻打泡。先关机，再拿出打奶头。':'轻轻搅打出一点空气感，注意不要溅出热奶。'}`},safe:'不要在摩卡壶内加热或打发牛奶。请使用适合你的工具的容器。',scene:t=>{let m=$('froth').value;return shadow()+pitcher()+ (m==='electric'?`<path d="M250 247 H345" stroke="#4f5b45" stroke-width="11" stroke-linecap="round"/><circle cx="295" cy="209" r="5" fill="#b3c88e"/>`:`<g transform="translate(${Math.sin(t*45)*3} 0)"><rect x="282" y="41" width="24" height="64" rx="10" fill="#58674c"/><path d="M294 102 V150" stroke="#a0ad96" stroke-width="4"/>${m==='wand'?'<ellipse cx="294" cy="150" rx="12" ry="3" stroke="#89977e" fill="none" stroke-width="3"/>':'<ellipse cx="294" cy="139" rx="9" ry="16" stroke="#89977e" fill="none" stroke-width="2"/>'}</g>`)+Array.from({length:12},(_,i)=>`<circle cx="${263+(i*17)%59}" cy="${134+(i*7)%12}" r="${1+(Math.sin(t*24+i)+1)*1.5}" fill="#fffbed"/>`).join('')+label(292,300,m==='electric'?'电动奶泡机 · 遵守奶量刻度':'打奶头留在奶中 · 细细的小泡泡') }},
{short:'倒入并混合',title:'调成你喜欢的温柔浓度。',desc:()=>`先往杯里倒入煮好的咖啡（你的两杯壶通常出液约 90 mL），再加入 ${$('milk').value} ml 温奶和一勺奶泡。尝一尝，喜欢更浓就再加一点咖啡。`,safe:'摩卡壶的“人份”是浓缩小杯。大壶会有多余咖啡；选足够大的杯子，避免倒满溢出。',scene:t=>{let milk=t>.5;return shadow()+mug(0,15,t>.1,t>.85)+`<g transform="translate(${milk?70:-110} -65) scale(.7) rotate(${milk?-25:25} 292 150)">${milk?pitcher():top()+base()}</g>`+(t<.88?`<path d="M${milk?354:232} 105 Q${milk?328:264} 127 300 169" stroke="${milk?'#fff2d8':'#785039'}" stroke-width="${milk?9:5}" fill="none" stroke-linecap="round"/>`:'')+label(293,310,milk?'倒入温奶，再加一点奶泡':'先加入适量摩卡咖啡') }},
{short:'慢慢享用',title:'你的咖啡小仪式，完成了。',desc:()=>`按自己的喜好做出一杯温暖奶咖。等摩卡壶完全冷却再打开，按厂家说明清洗、晾干。任何步骤都可以随时回看。`,safe:'壶热或仍有压力时，绝对不要拧开。握住手柄，注意防烫。',scene:t=>shadow()+mug(0,0,1,true)+steam(280,119,t)+`<text x="398" y="116" font-size="25" fill="#d9a271" transform="rotate(${Math.sin(t*6)*10} 398 116)">✦</text>`+label(300,299,'给早晨一段柔软的留白。')}
];

export {defs,shadow,label,base,top,basket,mug,pitcher,steam}; export function legacyScene(i,t,c){config=c;return steps[i].scene(t)}
